// Primary deck-list sections scraped from the linked GoatFormat guide pages.
// Each value is count|card-name; unlike the category fallback, the source
// ratio and even a published 39/41-card list are preserved verbatim.
function expand(spec) {
  return Object.freeze(spec.split(";").filter(Boolean).flatMap((entry) => {
    const separator = entry.indexOf("|");
    const count = Number(entry.slice(0, separator));
    const name = entry.slice(separator + 1);
    return Array.from({ length: count }, () => name);
  }));
}

